import{z as l,x as c,o as E,c as p,q as d,j as i,D as s,d as e,s as o,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"页缓存","description":"","frontmatter":{"title":"页缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-cache.md","filePath":"cs/page-cache.md","lastUpdated":1791063341000}'),B={name:"cs/page-cache.md"};function m(A,a,h,C,f,u){const t=c("Mermaid");return E(),p("div",null,[a[2]||(a[2]=d('<h1 id="页缓存" tabindex="-1">页缓存 <a class="header-anchor" href="#页缓存" aria-label="Permalink to &quot;页缓存&quot;">​</a></h1><div class="epigraph"><p>每个文件的数据页按文件偏移索引放在统一的页 Cache 里；read、write 与 mmap 看见同一帧。</p><footer>—— 据 McKusick 对缓冲缓存的演进；Bovet and Cesati 对 address_space 的整理</footer></div><p><a href="/cs/buffer-dirty">上一课</a>已经承认脏页与「同一物理块不应有两份副本」。缺口是把缓存收成<strong>按 inode 索引的页集合</strong>：不是块设备上的 512 字节缓冲槽那么老的主线，而是与 <a href="/cs/demand-paging">按需调页</a> 同一粒度的页。mmap 缺页填的就是这里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旧 Unix 缓冲缓存按设备+块号。文件空洞、大文件、mmap 需要按「文件偏移」找页，并允许稀疏。缺口：<code>address_space</code>（或等价物）用基数树/xarray 把索引 → 页框。<code>read</code> 拷到用户前先找页；未命中则 <code>readpage</code> 经 <a href="/cs/vfs">VFS</a> 让 FS 填。同一页可被多进程 mmap 共享。shrinker 从这里丢干净页。</p><p>本课不把 xarray 的内部节点写成算法课。</p><p><span class="marginnote">缓冲头（buffer_head）仍可把一页拆成多个盘块，对接非页对齐的块大小。教学上页是主对象，块是填充单位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查 inode 的页 Cache，miss 则向 <a href="/cs/buddy-allocator">buddy</a> 要页、发起读、插入树、拷贝或映射给用户。写：找或建页，改内容，标脏。匿名页不进这份按文件的树（它们走匿名 LRU）。与 dcache 分工不变：dentry 是名，页 Cache 是字节。</p>',9)),(E(),i(n,null,{default:s(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E6%96%87%E4%BB%B6%E5%81%8F%E7%A7%BB%22%5D%20--%3E%20TREE%5B%22inode%20%E9%A1%B5%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20HIT%5B%22%E5%90%8C%E4%B8%80%E5%B8%A7%E4%BE%9B%20read%2Fmmap%22%5D%0A%20%20TREE%20--%3E%20MISS%5B%22readpage%20%E5%A1%AB%E9%A1%B5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("页 Cache 让「磁盘是内存的下一层」可实现：热点文件留在 RAM，工作集可以主要是文件页。回收时丢掉它们等于缩小 Cache，不是杀进程。不要把页 Cache 当成 CPU 数据 Cache 的同构数字；缺失代价是毫秒级 I/O。数据库栏的缓冲池是用户态另一套，可以 "),r("code",null,"O_DIRECT"),e(" 绕过本课对象。")],-1)),a[5]||(a[5]=r("p",null,"内存紧张时，页缓存里的页按「脏不脏」分流：干净页在盘上有正本，直接丢；脏页带着未落盘的修改，必须先写回设备才能释放。这也解释了为什么写多的机器回收会变慢——回收被回写速度拖着。",-1)),(E(),i(n,null,{default:s(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEM%5B%22%E5%86%85%E5%AD%98%E7%B4%A7%E5%BC%A0%EF%BC%8Cshrinker%20%E6%89%AB%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%20--%3E%20K%7B%22%E8%BF%99%E4%B8%80%E9%A1%B5%E6%98%AF%E8%84%8F%E7%9A%84%E5%90%97%3F%22%7D%0A%20%20K%20--%3E%7C%22%E5%B9%B2%E5%87%80%22%7C%20DROP%5B%22%E7%9B%B4%E6%8E%A5%E4%B8%A2%EF%BC%9A%E7%9B%98%E4%B8%8A%E6%9C%89%E6%AD%A3%E6%9C%AC%22%5D%0A%20%20K%20--%3E%7C%22%E8%84%8F%22%7C%20WB%5B%22%E5%85%88%E5%86%99%E5%9B%9E%E8%AE%BE%E5%A4%87%22%5D%0A%20%20WB%20--%3E%20FREE%5B%22%E5%86%99%E5%AE%8C%E6%89%8D%E9%87%8A%E6%94%BE%E5%B8%A7%22%5D%0A%20%20DROP%20--%3E%20NEXT%5B%22%E8%85%BE%E5%87%BA%E7%9A%84%E5%B8%A7%E4%BA%A4%E7%BB%99%E6%96%B0%E5%88%86%E9%85%8D%22%5D%0A%20%20FREE%20--%3E%20NEXT%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<p><span class="marginnote">数字实例：<code>free -h</code> 里 buff/cache 的大头就是页缓存——首次读 1 GB 文件要几十毫秒到秒级（走盘），第二次同样读几乎瞬时（RAM 命中）；内存「被占满」未必是坏事，多半是缓存在等被回收。</span></p><p><span class="marginnote">直觉类比：页缓存像把常用书复印一份摆在桌上——read、mmap、再次 read 看的都是同一份复印件（同一帧）。干净页是「复印件与原书一致」，扔了随时再印；脏页是「复印件上写了批注」，必须先抄回原书才能扔。</span></p><p><span class="marginnote">常见误区：初学者容易把页缓存当 CPU 缓存的小兄弟。CPU 缓存缺失是纳秒级，页缓存缺失是毫秒级磁盘 I/O——差五个数量级；数据库才因此自管缓冲池，甚至用 O_DIRECT 整个绕开它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>fadvise</code> 的全部提示。不保证页 Cache 与块设备硬件 Cache 的一致性协议。下一课：脏页何时由谁写成队列，而不是等置换偶然碰到。</p><p>后课默认：文件字节在按偏移索引的页里。后台把脏页推向设备，下一课 writeback。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>页 Cache 按文件偏移索引帧；读写映射共用。</li><li>miss 走 VFS 的 readpage；shrinker 可丢干净页。</li><li>脏页的主动回写是 writeback 的缺口。</li><li>出处：McKusick et al., <em>4.4BSD</em>；Bovet and Cesati, <em>ULK</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const T=l(B,[["render",m]]);export{D as __pageData,T as default};
